     1	import Foundation
     2	
     3	/// `-RCDevWebMFault <spec>`, a dev-only launch default (dev tools only; codec-export C3 fix
     4	/// pass 1, spec §11 CX-15 (6)): one fault put into every `av1_webm` export of the launch, so
     5	/// a proof can show that a stop on either pump ends the export — each pump reads its own
     6	/// `AVAssetReader`, so neither read can be starved by the other's stop (G-17).
     7	///
     8	///   `audio@N`       the audio pump fails at its Nth read, before it
     9	///   `video@N`       the video sink fails at its Nth packet
    10	///   `audio-hold@N`  the audio pump waits `holdSeconds` at its Nth read, before it, without
    11	///                   looking at the stop flag — a read that is slow to return — then reads
    12	///
    13	/// Each firing is one log line, `framejob webm dev fault: …`, and with a fault set the
    14	/// writer logs its readers' states once both pumps have left (`framejob webm dev readers:
    15	/// video S, audio S`, with ` (one reader)` should the two ever be one object). Neither
    16	/// carries the parity check's prefix. Nil in a build without dev tools.
    17	///
    18	/// `-RCDevExportFault <spec>` (`writerKey`, spec §11 #378) is its sibling for `ExportWriter`
    19	/// (every MP4/MOV export of the launch): the same three faults in its audio pump (before a
    20	/// read) and its plain video pump (before an append), each line `framejob export dev …`.
    21	final class ExportWebMDevFault {
    22	    static let key = "RCDevWebMFault"
    23	    static let writerKey = "RCDevExportFault"
    24	    static let holdSeconds = 3.0
    25	
    26	    enum Kind: String { case audio, video, audioHold = "audio-hold" }
    27	
    28	    let kind: Kind
    29	    let at: Int
    30	    /// The log lines' word: `webm` for `key`, `export` for `writerKey`.
    31	    private let word: String
    32	
    33	    private init(kind: Kind, at: Int, word: String) {
    34	        self.kind = kind
    35	        self.at = at
    36	        self.word = word
    37	    }
    38	
    39	    @available(*, unavailable) required init?(coder: NSCoder) {
    40	        fatalError("ExportWebMDevFault does not support NSCoder")
    41	    }
    42	
    43	    /// The launch's fault under `key`, or nil (none set, malformed, or no dev tools).
    44	    static func current(key: String = ExportWebMDevFault.key) -> ExportWebMDevFault? {
    45	        #if FRAMEJOB_DEV_TOOLS
    46	        guard let spec = UserDefaults.standard.string(forKey: key) else { return nil }
    47	        let parts = spec.split(separator: "@", maxSplits: 1).map(String.init)
    48	        guard parts.count == 2, let kind = Kind(rawValue: parts[0]), let at = Int(parts[1]),
    49	            at > 0
    50	        else { return nil }
    51	        return ExportWebMDevFault(kind: kind, at: at, word: key == writerKey ? "export" : "webm")
    52	        #else
    53	        return nil
    54	        #endif
    55	    }
    56	
    57	    /// The audio pump, before its read number `read` (from 1): throws at `audio@N`, waits at
    58	    /// `audio-hold@N`.
    59	    func beforeAudioRead(_ read: Int) throws {
    60	        guard read == at else { return }
    61	        switch kind {
    62	        case .audio:
    63	            note("fault: the audio pump fails at read \(read)")
    64	            throw Exporter.ExportError.failed("A dev fault stopped the audio at read \(read).")
    65	        case .audioHold:
    66	            note("fault: the audio read \(read) is held \(Self.holdSeconds) s")
    67	            Thread.sleep(forTimeInterval: Self.holdSeconds)
    68	            note("fault: the audio read \(read) goes on")
    69	        case .video:
    70	            return
    71	        }
    72	    }
    73	
    74	    /// The video sink, at its packet number `packet` (from 1): the failure at `video@N`.
    75	    func videoPacket(_ packet: Int) -> (any Error)? {
    76	        guard kind == .video, packet == at else { return nil }
    77	        note("fault: the video sink fails at packet \(packet)")
    78	        return Exporter.ExportError.failed("A dev fault stopped the video at packet \(packet).")
    79	    }
    80	
    81	    /// One line in this fault's word: `framejob webm dev …` or `framejob export dev …`.
    82	    func note(_ line: String) {
    83	        NSLog("framejob %@ dev %@", word, line)
    84	    }
    85	
    86	    static func log(_ line: String) {
    87	        NSLog("framejob webm dev %@", line)
    88	    }
    89	}
